input.command:
chmod 755 /var/lib/mailman3 /var/lib/mailman3/data; PW=$(grep -m1 '^admin_pass' /etc/mailman3/mailman.cfg | awk '{print $2}'); U=$(grep -m1 '^admin_user' /etc/mailman3/mailman.cfg | awk '{print $2}');
curl -s -u "$U:$PW" -X PATCH http://localhost:8001/3.1/lists/reading-group.local.edu/config -d subscription_policy=confirm -d unsubscription_policy=confirm -d default_member_action=accept -d default_nonmember_action=accept -d advertised=True -d max_message_size=0 -w '\nHTTP %{http_code}\n';
curl -s -u "$U:$PW" http://localhost:8001/3.1/lists/reading-group.local.edu/config | python3 -m json.tool | grep -E 'subscription_policy|unsubscription|default_(non)?member_action|posting_pipeline|send_welcome'
